export const SCROLL_ID = "ntu-scroll";

/**
 * 這些 flow 直接進 AI 對話，不顯示快速常見問答、不跑 QA 資料庫搜尋。
 * 3 = 簡易模式；6 = Gemini File Search RAG（個人文件問答）；7 = 學習規劃探索助手（Gemini 多輪對話，
 * 正式入口已改為 /explore/ 沉浸式體驗，這裡的聊天 UI 只在 VITE_EXPLORE_URL 未設定時當 fallback）；
 * 8 = 未來教室設備支援助理（Gemini 多輪對話，可附加照片問問題）；
 * 9 = 學習規劃探索助手的舊版通用聊天 UI（跟 7 共用同一個後端 AdvisingChatService）。
 */
export const SIMPLE_MODE_FLOW_IDS = ["3", "6", "7", "8", "9"];

export const NPS_ENDPOINT =
  "https://script.google.com/macros/s/AKfycbzZEF0pLOc2puEz8nsAaAqaRr79aOIxh2lSY8JYuahqp9opeuM5Qti93mT20LnAjOiq/exec";

export enum LocalStorageKey {
  JWT_TOKEN = "auth.jwt_token",
  POLICY_ACCEPTED = "app.policy_accepted",
}

export enum TokenKey {
  CHINESE_NAME = "http://www.ntu.edu.tw/ChineseName",
  ACCOUNT_NAME = "http://www.ntu.edu.tw/AccountName",
  ACCOUNT_TYPE = "http://www.ntu.edu.tw/AccountTypeCode",
}

