using chatai.Adapter.Chatai.Common;
using Microsoft.Data.SqlClient;
using ntu.Adapter.Core.Common;
using System.Data;

namespace chatai.Adapter.Chatai.Command
{
    internal static class ExplorationAdapter
    {
        /// <summary>
        /// 取得探索紀錄，呼叫端要自行核對 account_name 是不是目前登入的使用者，
        /// 這裡只依 id 撈資料，不做歸屬檢查。
        /// </summary>
        internal static DTO.Exploration? GetExplorationById(Guid id)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
            };

            return MsSqlProxy.Query<DTO.Exploration>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.GetExplorationById, parameters);
        }

        /// <summary>
        /// 取得某個帳號的所有探索紀錄，依更新時間新到舊排序。
        /// </summary>
        internal static IEnumerable<DTO.Exploration> GetExplorationListForAccount(string accountName)
        {
            SqlParameter[] parameters =
            {
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
            };

            return MsSqlProxy.QueryCollection<DTO.Exploration>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.GetExplorationListForAccount, parameters);
        }

        internal static bool AddExploration(DTO.Exploration exploration)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = exploration.id },
                new("account_name", SqlDbType.NVarChar) { Value = exploration.account_name },
                new("topic", SqlDbType.VarChar) { Value = exploration.topic },
                new("topic_custom_label", SqlDbType.NVarChar) { Value = (object?)exploration.topic_custom_label ?? DBNull.Value },
                new("status", SqlDbType.VarChar) { Value = exploration.status },
                new("history_json", SqlDbType.NVarChar) { Value = exploration.history_json },
                new("answers_json", SqlDbType.NVarChar) { Value = (object?)exploration.answers_json ?? DBNull.Value },
                new("summary_json", SqlDbType.NVarChar) { Value = (object?)exploration.summary_json ?? DBNull.Value },
                new("card_json", SqlDbType.NVarChar) { Value = (object?)exploration.card_json ?? DBNull.Value },
                new("fast_json", SqlDbType.NVarChar) { Value = (object?)exploration.fast_json ?? DBNull.Value },
                new("is_del", SqlDbType.Bit) { Value = exploration.is_del },
                new("create_date", SqlDbType.DateTime) { Value = exploration.create_date },
                new("update_date", SqlDbType.DateTime) { Value = exploration.update_date },
            };

            return MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.AddExploration, parameters) >= 1;
        }

        /// <summary>
        /// 只更新 history_json（AI 對話的權威狀態），見 RunController.RunAdvisingExploreFlow。
        /// WHERE 子句同時帶 account_name，即使呼叫端忘記事先核對歸屬，也不會誤寫到別人的紀錄。
        /// </summary>
        internal static bool UpdateExplorationHistory(Guid id, string accountName, string historyJson, DateTime updateDate)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("history_json", SqlDbType.NVarChar) { Value = historyJson },
                new("update_date", SqlDbType.DateTime) { Value = updateDate },
            };

            return MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.UpdateExplorationHistory, parameters) >= 1;
        }

        /// <summary>
        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位，
        /// 不影響 history_json（AI 對話狀態）。
        /// </summary>
        internal static bool UpdateExplorationDerived(
            Guid id,
            string accountName,
            string? answersJson,
            string? summaryJson,
            string? cardJson,
            string? fastJson,
            string status,
            DateTime updateDate)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("answers_json", SqlDbType.NVarChar) { Value = (object?)answersJson ?? DBNull.Value },
                new("summary_json", SqlDbType.NVarChar) { Value = (object?)summaryJson ?? DBNull.Value },
                new("card_json", SqlDbType.NVarChar) { Value = (object?)cardJson ?? DBNull.Value },
                new("fast_json", SqlDbType.NVarChar) { Value = (object?)fastJson ?? DBNull.Value },
                new("status", SqlDbType.VarChar) { Value = status },
                new("update_date", SqlDbType.DateTime) { Value = updateDate },
            };

            return MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.UpdateExplorationDerived, parameters) >= 1;
        }

        /// <summary>
        /// 後台管理用：依帳號彙總探索紀錄統計，支援帳號模糊搜尋、分頁。
        /// </summary>
        internal static (int totalCount, IEnumerable<DTO.ExplorationAccountSummary> data) GetExplorationAccountSummaryList(int pageSize, int page, string accountName)
        {
            SqlParameter[] parameters =
            {
                new("offset", SqlDbType.Int) { Value = (page - 1) * pageSize },
                new("page_size", SqlDbType.Int) { Value = pageSize },
            };

            // 注意：這裡一定要放「長度 1、內容可為空字串」的陣列，不能在沒有搜尋值時放空陣列（Length 0）。
            // MsSqlProxy.QueryMultipleWithLike 只要偵測到 parametersLike 裡任何一個 key 對到長度 0 的陣列，
            // 會直接短路回傳空結果（把它當成「IN 條件的候選值是空集合，注定查不到」），不會執行查詢。
            // 空字串包成長度 1 的陣列時，會變成 LIKE '%%'，等同於不篩選，才能正確「顯示全部帳號」。
            var parametersLike = new Dictionary<string, string[]>
            {
                { "account_name", new[] { accountName ?? string.Empty } }
            };

            return MsSqlProxy.QueryMultipleWithLike<DTO.ExplorationAccountSummary>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.GetExplorationAccountSummaryList, parametersLike, parameters);
        }

        /// <summary>
        /// 後台管理用：查詢單一帳號（精準比對）的探索紀錄，支援狀態篩選、分頁。
        /// </summary>
        internal static (int totalCount, IEnumerable<DTO.Exploration> data) GetExplorationListByAccount(int pageSize, int page, string accountName, string status)
        {
            SqlParameter[] parameters =
            {
                new("offset", SqlDbType.Int) { Value = (page - 1) * pageSize },
                new("page_size", SqlDbType.Int) { Value = pageSize },
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("status", SqlDbType.VarChar) { Value = status ?? string.Empty },
            };

            return MsSqlProxy.QueryMultipleCollection<DTO.Exploration>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.GetExplorationListByAccount, parameters);
        }

        internal static bool DeleteExploration(Guid id, string accountName, DateTime updateDate)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("update_date", SqlDbType.DateTime) { Value = updateDate },
            };

            return MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.DeleteExploration, parameters) >= 1;
        }
    }
}

