namespace chatai.Adapter.Chatai.DTO
{
    /// <summary>
    /// flowId=7（學習規劃探索助手）的探索紀錄，對應 [dbo].[exploration] 資料表。
    /// answers/summary/card/fast 這幾個巢狀結構固定用 JSON 字串欄位存（*_json），
