17	    [Route("api/run")]
18	    [NeedSignature]
19	    public class RunController : BaseApiController
20	    {
21	        /// <summary>
22	        /// flowId=6 走 Gemini File Search RAG，不再 proxy 到 Langflow
23	        /// </summary>
24	        private const int GeminiFlowIndex = 6;
25	
26	        /// <summary>
27	        /// flowId=7：學習規劃探索助手（explore 沉浸式體驗），直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
28	        /// </summary>
29	        private const int AdvisingFlowIndex = 7;
30	
31	        /// <summary>
32	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
33	        /// </summary>
34	        private const int ClassroomFaqFlowIndex = 8;
35	
36	        /// <summary>
37	        /// flowId=9：「學習規劃探索助手」通用聊天 UI，跟 flowId=7（explore 沉浸式體驗）
38	        /// 共用同一個 AdvisingChatService，也共用同一套 exploration 持久化路徑
39	        /// （見 RunAdvisingExploreFlow）——只是前端呈現方式不同（一個是聊天氣泡、一個是沉浸式體驗），
40	        /// 建立 exploration 時帶的 channel 不同（'chat' vs 'explore'）。
41	        /// </summary>
42	        private const int AdvisingChatUiFlowIndex = 9;
43	
44	        private readonly IHttpClientFactory _httpClientFactory;
45	        private readonly AppSettingConfig _appSetting;
46	        private readonly SignatureContext _signatureContext;
47	        private readonly IGeminiFileSearchService _geminiService;
48	        private readonly IAdvisingChatService _advisingService;
49	        private readonly IClassroomFaqChatService _classroomFaqService;
50	        private readonly IChataiModule _chataiModule;
51	        private readonly ILogger<RunController> _logger;
52	
53	        public RunController(
54	            IHttpClientFactory httpClientFactory,
55	            AppSettingConfig appSetting,
56	            SignatureContext signatureContext,
57	            IGeminiFileSearchService geminiService,
58	            IAdvisingChatService advisingService,
59	            IClassroomFaqChatService classroomFaqService,
60	            IChataiModule chataiModule,
61	            ILogger<RunController> logger)
62	        {
63	            _httpClientFactory = httpClientFactory;
64	            _appSetting = appSetting;
65	            _signatureContext = signatureContext;
66	            _geminiService = geminiService;
67	            _advisingService = advisingService;
68	            _classroomFaqService = classroomFaqService;
69	            _chataiModule = chataiModule;
70	            _logger = logger;
71	        }
72	
73	        [HttpGet]
74	        public IActionResult Get()
75	        {
76	            return Content("");
77	        }
78	
79	        [HttpPost]
80	        public async Task<IActionResult> Post([FromBody] JsonElement body)
81	        {
82	            var apiFlowIndex = _signatureContext.apiFlow;
83	
84	            if (apiFlowIndex == GeminiFlowIndex)
85	                return await RunGeminiFlow(body);
86	
87	            // flowId=7（explore 沉浸式體驗）跟 flowId=9（通用聊天 UI）的對話紀錄都由後端管理，
88	            // 共用同一套 exploration 持久化路徑，見 RunAdvisingExploreFlow。
89	            if (apiFlowIndex == AdvisingFlowIndex || apiFlowIndex == AdvisingChatUiFlowIndex)
90	                return await RunAdvisingExploreFlow(body, apiFlowIndex);
91	
92	            if (apiFlowIndex == ClassroomFaqFlowIndex)
93	                return await RunClassroomFaqFlow(body);
94	
95	            var apiUrl = _appSetting.ApiUrl;
96	            var apiKey = _appSetting.ApiKey;
97	            var flowIds = _appSetting.FlowIds;
98	
99	            if (string.IsNullOrEmpty(apiUrl)
100	                || string.IsNullOrEmpty(apiKey)
101	                || flowIds == null
102	                || !flowIds.Any())
103	                throw new Exception("Missing configuration values.");
104	
105	            //var stream = HttpContext.Request.Query["stream"].ToNullString().ToBoolean().ToString().ToLower();
106	
107	            if (flowIds.Count() <= apiFlowIndex)
108	                return BadRequest("Invalid API flow index.");
109	
110	            var flowId = flowIds.Skip(apiFlowIndex).First();
111	
112	            var targetUrl = $"{apiUrl}/api/v1/run/{flowId}";//?stream={stream}
113	
114	            using var client = _httpClientFactory.CreateClient("NoSsl");
115	            var json = body.GetRawText();
116	            var jsonBytes = Encoding.UTF8.GetBytes(json);
117	            using var content = new ByteArrayContent(jsonBytes)
118	            {
119	                Headers =
120	                {
121	                    ContentType = new MediaTypeHeaderValue("application/json"),
122	                    ContentLength = jsonBytes.Length
123	                }
124	            };
125	
126	            var requestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl)
127	            {
128	                Content = content
129	            };
130	
131	            requestMessage.Content?.Headers.TryAddWithoutValidation("x-api-key", apiKey);
132	
133	            var response = await client.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
134	            var responseBody = await response.Content.ReadAsStringAsync();
135	
136	            Response.Headers.Append("x-flow", $"{apiFlowIndex}");
137	
138	            return Content(responseBody, response.Content.Headers.ContentType?.ToString() ?? "application/json");
139	        }
140	
141	        /// <summary>
142	        /// flowId=6：改用 Gemini File Search 做 RAG，以 SSE 串流方式即時把答案文字吐給前端，
143	        /// 每個 event 是一行 `data: {...}\n\n`，格式為 { delta, source, done, error }。
144	        /// </summary>
145	        private async Task<IActionResult> RunGeminiFlow(JsonElement body)
146	        {
147	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
148	            if (string.IsNullOrEmpty(userId))
149	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
150	
151	            if (!body.TryGetProperty("input_value", out var inputValueEl))
152	                return BadRequest("Missing input_value.");
153	
154	            var inputValue = inputValueEl.GetString() ?? "";
155	
156	            Response.ContentType = "text/event-stream";
157	            Response.Headers.Append("Cache-Control", "no-cache");
158	            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");
159	
160	            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
161	            {
162	                var payload = JsonSerializer.Serialize(new
163	                {
164	                    delta = chunk.Delta,
165	                    source = chunk.Source,
166	                    done = chunk.Done,
167	                    error = chunk.Error,
168	                });
169	                await Response.WriteAsync($"data: {payload}\n\n");
170	                await Response.Body.FlushAsync();
171	            }
172	
173	            return new EmptyResult();
174	        }
175	
176	        /// <summary>
177	        /// flowId=7（explore 沉浸式體驗）／flowId=9（通用聊天 UI）共用：直接呼叫 Gemini 做多輪對話，
178	        /// 以 SSE 串流方式即時把答案文字吐給前端。對話紀錄由後端管理：前端只帶 exploration_id +
179	        /// input_value，history 從 [dbo].[exploration] 讀出來，串流結束後把這輪（使用者輸入＋AI 完整
180	        /// 回覆）append 回去存下。這樣前端沒辦法透過竄改 history 操控 Critical Conversation State Rule
181	        /// 判斷的階段，且不用每輪都整包重送歷史。兩個 flow 差別只在建立 exploration 時的 channel
182	        /// （'explore' vs 'chat'，見 ExplorationController.Create），這裡的對話邏輯完全共用。
183	        /// accountName 只用來核對 exploration 的歸屬，不會傳進 _advisingService.QueryStreamAsync——
184	        /// 那個方法一直以來就只吃 question + history 兩個純文字參數，SSO 身份資訊不會流向 AI。
185	        /// </summary>
186	        private async Task<IActionResult> RunAdvisingExploreFlow(JsonElement body, int apiFlowIndex)
187	        {
188	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
189	            if (string.IsNullOrEmpty(userId))
190	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
191	
192	            if (!body.TryGetProperty("exploration_id", out var explorationIdEl) ||
193	                !Guid.TryParse(explorationIdEl.GetString(), out var explorationId))
194	                return BadRequest("Missing or invalid exploration_id.");
195	
196	            if (!body.TryGetProperty("input_value", out var inputValueEl))
197	                return BadRequest("Missing input_value.");
198	
199	            var inputValue = inputValueEl.GetString() ?? "";
200	
201	            // 空白內容不能往下走：這輪成功後會被原封不動存進 history_json（見下方 history.Add），
202	            // Claude/Gemini 的多輪對話 API 都不接受空字串的訊息內容，一旦存進去，這筆探索之後
203	            // 每輪都要重送整段 history，會永久卡在同一個錯誤（見 ExplorationHistoryJson.Parse
204	            // 的自動過濾說明——那是幫已經中招的舊資料復原，這裡是從源頭擋掉新的個案）。
205	            if (string.IsNullOrWhiteSpace(inputValue))
206	                return BadRequest("input_value 不可為空白。");
207	
208	            var record = _chataiModule.GetExplorationById(explorationId);
209	            if (record == null || record.is_del || record.account_name != userId)
210	                return NotFound("找不到探索紀錄，或這筆紀錄不屬於目前登入的使用者。");
211	
212	            var history = ExplorationHistoryJson.Parse(record.history_json);
213	
214	            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
215	            var model = "gemini";
216	            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
217	            {
218	                var requestedModel = modelEl.GetString();
219	                if (!string.IsNullOrWhiteSpace(requestedModel))
220	                    model = requestedModel;
221	            }
222	
223	            Response.ContentType = "text/event-stream";
224	            Response.Headers.Append("Cache-Control", "no-cache");
225	            Response.Headers.Append("x-flow", $"{apiFlowIndex}");
226	
227	            var replyBuilder = new StringBuilder();
228	            var streamFailed = false;
229	
230	            await foreach (var chunk in _advisingService.QueryStreamAsync(inputValue, history, model))
231	            {
232	                if (!string.IsNullOrEmpty(chunk.Delta))
233	                    replyBuilder.Append(chunk.Delta);
234	                if (!string.IsNullOrEmpty(chunk.Error))
235	                    streamFailed = true;
236	
237	                var payload = JsonSerializer.Serialize(new
238	                {
239	                    delta = chunk.Delta,
240	                    source = chunk.Source,
241	                    done = chunk.Done,
242	                    error = chunk.Error,
243	                });
244	                await Response.WriteAsync($"data: {payload}\n\n");
245	                await Response.Body.FlushAsync();
246	            }
247	
248	            // 串流中途失敗（額度/限流等）就不要把這輪寫回歷史，避免存進一段不完整或空白的 AI 回覆，
249	            // 讓使用者下次重送時還是接在最後一個成功的完整回合之後。
250	            if (!streamFailed && replyBuilder.Length > 0)
251	            {
252	                history.Add(("user", inputValue));
253	                history.Add(("model", replyBuilder.ToString()));
254	                _chataiModule.UpdateExplorationHistory(explorationId, userId, ExplorationHistoryJson.Serialize(history), DateTime.Now);
255	            }
256	
257	            return new EmptyResult();
258	        }
259	
260	        /// <summary>
261	        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini 做多輪對話（可附加一張照片做單次視覺問答），
262	        /// 以 SSE 串流方式即時把答案文字吐給前端。多輪對話紀錄由前端透過 body.history 每次完整帶入。
263	        /// </summary>
264	        private async Task<IActionResult> RunClassroomFaqFlow(JsonElement body)
265	        {
266	            var ipWhitelist = _appSetting.ClassroomFaqIpWhitelist;
267	            if (ipWhitelist is { Count: > 0 })
268	            {
269	                var clientIp = IpHelper.GetClientIpAddress(HttpContext);
270	                if (!IpHelper.IsMatchIpAddress(new[] { clientIp }, ipWhitelist))
271	                {
272	                    _logger.LogWarning("flow=8 拒絕來源 IP {ClientIp} 存取。", clientIp);
273	                    return StatusCode(StatusCodes.Status403Forbidden, "此功能僅開放特定網路環境使用，請洽數位學習中心。");
274	                }
275	            }
276	
277	            var userId = JWTHelper.GetAccountNameFromRequest(Request);
278	            if (string.IsNullOrEmpty(userId))
279	                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");
280	
281	            if (!body.TryGetProperty("input_value", out var inputValueEl))
282	                return BadRequest("Missing input_value.");
283	
284	            var inputValue = inputValueEl.GetString() ?? "";
285	
286	            var history = new List<(string Role, string Text)>();
287	            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
288	            {
289	                foreach (var item in historyEl.EnumerateArray())
290	                {
291	                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
292	                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
293	                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
294	                        continue;
295	                    history.Add((role, text));
296	                }
297	            }
298	
299	            (string MimeType, string Base64Data)? image = null;
300	            if (body.TryGetProperty("image", out var imageEl) && imageEl.ValueKind == JsonValueKind.Object)
301	            {
302	                var mimeType = imageEl.TryGetProperty("mimeType", out var mimeEl) ? mimeEl.GetString() : null;
303	                var data = imageEl.TryGetProperty("data", out var dataEl) ? dataEl.GetString() : null;
304	                if (!string.IsNullOrEmpty(mimeType) && !string.IsNullOrEmpty(data))
305	                    image = (mimeType, data);
306	            }
307	
308	            Response.ContentType = "text/event-stream";
309	            Response.Headers.Append("Cache-Control", "no-cache");
310	            Response.Headers.Append("x-flow", $"{ClassroomFaqFlowIndex}");
311	
312	            await foreach (var chunk in _classroomFaqService.QueryStreamAsync(inputValue, history, image))
313	            {
314	                var payload = JsonSerializer.Serialize(new
315	                {
316	                    delta = chunk.Delta,
317	                    source = chunk.Source,
318	                    done = chunk.Done,
319	                    error = chunk.Error,
320	                });
321	                await Response.WriteAsync($"data: {payload}\n\n");
322	                await Response.Body.FlushAsync();
323	            }
324	
325	            return new EmptyResult();
326	        }
327	    }
