        private const int AdvisingFlowIndex = 7;

        /// <summary>
        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini（不用 file_search），不再 proxy 到 Langflow
        /// </summary>
        private const int ClassroomFaqFlowIndex = 8;

        /// <summary>
        /// flowId=9：「學習規劃探索助手」通用聊天 UI，跟 flowId=7（explore 沉浸式體驗）
        /// 共用同一個 AdvisingChatService，也共用同一套 exploration 持久化路徑
        /// （見 RunAdvisingExploreFlow）——只是前端呈現方式不同（一個是聊天氣泡、一個是沉浸式體驗），
        /// 建立 exploration 時帶的 channel 不同（'chat' vs 'explore'）。
        /// </summary>
        private const int AdvisingChatUiFlowIndex = 9;

        private readonly IHttpClientFactory _httpClientFactory;
        private readonly AppSettingConfig _appSetting;
        private readonly SignatureContext _signatureContext;
        private readonly IGeminiFileSearchService _geminiService;
        private readonly IAdvisingChatService _advisingService;
        private readonly IClassroomFaqChatService _classroomFaqService;
        private readonly IChataiModule _chataiModule;
        private readonly ILogger<RunController> _logger;

        public RunController(
            IHttpClientFactory httpClientFactory,
            AppSettingConfig appSetting,
            SignatureContext signatureContext,
            IGeminiFileSearchService geminiService,
            IAdvisingChatService advisingService,
            IClassroomFaqChatService classroomFaqService,
            IChataiModule chataiModule,
            ILogger<RunController> logger)
        {
            _httpClientFactory = httpClientFactory;
            _appSetting = appSetting;
            _signatureContext = signatureContext;
            _geminiService = geminiService;
            _advisingService = advisingService;
            _classroomFaqService = classroomFaqService;
            _chataiModule = chataiModule;
            _logger = logger;
        }

        [HttpGet]
        public IActionResult Get()
        {
            return Content("");
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] JsonElement body)
        {
            var apiFlowIndex = _signatureContext.apiFlow;

            if (apiFlowIndex == GeminiFlowIndex)
                return await RunGeminiFlow(body);

            // flowId=7（explore 沉浸式體驗）跟 flowId=9（通用聊天 UI）的對話紀錄都由後端管理，
            // 共用同一套 exploration 持久化路徑，見 RunAdvisingExploreFlow。
            if (apiFlowIndex == AdvisingFlowIndex || apiFlowIndex == AdvisingChatUiFlowIndex)
                return await RunAdvisingExploreFlow(body, apiFlowIndex);

            if (apiFlowIndex == ClassroomFaqFlowIndex)
                return await RunClassroomFaqFlow(body);

            var apiUrl = _appSetting.ApiUrl;
            var apiKey = _appSetting.ApiKey;
            var flowIds = _appSetting.FlowIds;

            if (string.IsNullOrEmpty(apiUrl)
                || string.IsNullOrEmpty(apiKey)
                || flowIds == null
                || !flowIds.Any())
                throw new Exception("Missing configuration values.");

            //var stream = HttpContext.Request.Query["stream"].ToNullString().ToBoolean().ToString().ToLower();

            if (flowIds.Count() <= apiFlowIndex)
                return BadRequest("Invalid API flow index.");

            var flowId = flowIds.Skip(apiFlowIndex).First();

            var targetUrl = $"{apiUrl}/api/v1/run/{flowId}";//?stream={stream}

            using var client = _httpClientFactory.CreateClient("NoSsl");
            var json = body.GetRawText();
            var jsonBytes = Encoding.UTF8.GetBytes(json);
            using var content = new ByteArrayContent(jsonBytes)
            {
                Headers =
                {
                    ContentType = new MediaTypeHeaderValue("application/json"),
                    ContentLength = jsonBytes.Length
                }
            };

            var requestMessage = new HttpRequestMessage(HttpMethod.Post, targetUrl)
            {
                Content = content
            };

            requestMessage.Content?.Headers.TryAddWithoutValidation("x-api-key", apiKey);

            var response = await client.SendAsync(requestMessage, HttpCompletionOption.ResponseHeadersRead);
            var responseBody = await response.Content.ReadAsStringAsync();

            Response.Headers.Append("x-flow", $"{apiFlowIndex}");

            return Content(responseBody, response.Content.Headers.ContentType?.ToString() ?? "application/json");
        }

        /// <summary>
        /// flowId=6：改用 Gemini File Search 做 RAG，以 SSE 串流方式即時把答案文字吐給前端，
        /// 每個 event 是一行 `data: {...}\n\n`，格式為 { delta, source, done, error }。
        /// </summary>
        private async Task<IActionResult> RunGeminiFlow(JsonElement body)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (!body.TryGetProperty("input_value", out var inputValueEl))
                return BadRequest("Missing input_value.");

            var inputValue = inputValueEl.GetString() ?? "";

            Response.ContentType = "text/event-stream";
            Response.Headers.Append("Cache-Control", "no-cache");
            Response.Headers.Append("x-flow", $"{GeminiFlowIndex}");

            await foreach (var chunk in _geminiService.QueryStreamAsync(inputValue, userId))
            {
                var payload = JsonSerializer.Serialize(new
                {
                    delta = chunk.Delta,
                    source = chunk.Source,
                    done = chunk.Done,
                    error = chunk.Error,
                });
                await Response.WriteAsync($"data: {payload}\n\n");
                await Response.Body.FlushAsync();
            }

            return new EmptyResult();
        }

        /// <summary>
        /// flowId=7（explore 沉浸式體驗）／flowId=9（通用聊天 UI）共用：直接呼叫 Gemini 做多輪對話，
        /// 以 SSE 串流方式即時把答案文字吐給前端。對話紀錄由後端管理：前端只帶 exploration_id +
        /// input_value，history 從 [dbo].[exploration] 讀出來，串流結束後把這輪（使用者輸入＋AI 完整
        /// 回覆）append 回去存下。這樣前端沒辦法透過竄改 history 操控 Critical Conversation State Rule
        /// 判斷的階段，且不用每輪都整包重送歷史。兩個 flow 差別只在建立 exploration 時的 channel
        /// （'explore' vs 'chat'，見 ExplorationController.Create），這裡的對話邏輯完全共用。
        /// accountName 只用來核對 exploration 的歸屬，不會傳進 _advisingService.QueryStreamAsync——
        /// 那個方法一直以來就只吃 question + history 兩個純文字參數，SSO 身份資訊不會流向 AI。
        /// </summary>
        private async Task<IActionResult> RunAdvisingExploreFlow(JsonElement body, int apiFlowIndex)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (!body.TryGetProperty("exploration_id", out var explorationIdEl) ||
                !Guid.TryParse(explorationIdEl.GetString(), out var explorationId))
                return BadRequest("Missing or invalid exploration_id.");

            if (!body.TryGetProperty("input_value", out var inputValueEl))
                return BadRequest("Missing input_value.");

            var inputValue = inputValueEl.GetString() ?? "";

            // 空白內容不能往下走：這輪成功後會被原封不動存進 history_json（見下方 history.Add），
            // Claude/Gemini 的多輪對話 API 都不接受空字串的訊息內容，一旦存進去，這筆探索之後
            // 每輪都要重送整段 history，會永久卡在同一個錯誤（見 ExplorationHistoryJson.Parse
            // 的自動過濾說明——那是幫已經中招的舊資料復原，這裡是從源頭擋掉新的個案）。
            if (string.IsNullOrWhiteSpace(inputValue))
                return BadRequest("input_value 不可為空白。");

            var record = _chataiModule.GetExplorationById(explorationId);
            if (record == null || record.is_del || record.account_name != userId)
                return NotFound("找不到探索紀錄，或這筆紀錄不屬於目前登入的使用者。");

            var history = ExplorationHistoryJson.Parse(record.history_json);

            // 前端透過 ?model= 帶入（例如 /?flow=7&model=claude），對應 body.model；未帶則預設 gemini
            var model = "gemini";
            if (body.TryGetProperty("model", out var modelEl) && modelEl.ValueKind == JsonValueKind.String)
            {
                var requestedModel = modelEl.GetString();
                if (!string.IsNullOrWhiteSpace(requestedModel))
                    model = requestedModel;
            }

            Response.ContentType = "text/event-stream";
            Response.Headers.Append("Cache-Control", "no-cache");
            Response.Headers.Append("x-flow", $"{apiFlowIndex}");

            var replyBuilder = new StringBuilder();
            var streamFailed = false;

            await foreach (var chunk in _advisingService.QueryStreamAsync(inputValue, history, model))
            {
                if (!string.IsNullOrEmpty(chunk.Delta))
                    replyBuilder.Append(chunk.Delta);
                if (!string.IsNullOrEmpty(chunk.Error))
                    streamFailed = true;

                var payload = JsonSerializer.Serialize(new
                {
                    delta = chunk.Delta,
                    source = chunk.Source,
                    done = chunk.Done,
                    error = chunk.Error,
                });
                await Response.WriteAsync($"data: {payload}\n\n");
                await Response.Body.FlushAsync();
            }

            // 串流中途失敗（額度/限流等）就不要把這輪寫回歷史，避免存進一段不完整或空白的 AI 回覆，
            // 讓使用者下次重送時還是接在最後一個成功的完整回合之後。
            if (!streamFailed && replyBuilder.Length > 0)
            {
                history.Add(("user", inputValue));
                history.Add(("model", replyBuilder.ToString()));
                _chataiModule.UpdateExplorationHistory(explorationId, userId, ExplorationHistoryJson.Serialize(history), DateTime.Now);
            }

            return new EmptyResult();
        }

        /// <summary>
        /// flowId=8：未來教室設備支援助理，直接呼叫 Gemini 做多輪對話（可附加一張照片做單次視覺問答），
        /// 以 SSE 串流方式即時把答案文字吐給前端。多輪對話紀錄由前端透過 body.history 每次完整帶入。
        /// </summary>
        private async Task<IActionResult> RunClassroomFaqFlow(JsonElement body)
        {
            var ipWhitelist = _appSetting.ClassroomFaqIpWhitelist;
            if (ipWhitelist is { Count: > 0 })
            {
                var clientIp = IpHelper.GetClientIpAddress(HttpContext);
                if (!IpHelper.IsMatchIpAddress(new[] { clientIp }, ipWhitelist))
                {
                    _logger.LogWarning("flow=8 拒絕來源 IP {ClientIp} 存取。", clientIp);
                    return StatusCode(StatusCodes.Status403Forbidden, "此功能僅開放特定網路環境使用，請洽數位學習中心。");
                }
            }

            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (!body.TryGetProperty("input_value", out var inputValueEl))
                return BadRequest("Missing input_value.");

            var inputValue = inputValueEl.GetString() ?? "";

            var history = new List<(string Role, string Text)>();
            if (body.TryGetProperty("history", out var historyEl) && historyEl.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in historyEl.EnumerateArray())
                {
                    var role = item.TryGetProperty("role", out var roleEl) ? roleEl.GetString() : null;
                    var text = item.TryGetProperty("text", out var textEl) ? textEl.GetString() : null;
                    if (string.IsNullOrEmpty(role) || string.IsNullOrEmpty(text))
                        continue;
                    history.Add((role, text));
                }
            }

            (string MimeType, string Base64Data)? image = null;
            if (body.TryGetProperty("image", out var imageEl) && imageEl.ValueKind == JsonValueKind.Object)
            {
                var mimeType = imageEl.TryGetProperty("mimeType", out var mimeEl) ? mimeEl.GetString() : null;
                var data = imageEl.TryGetProperty("data", out var dataEl) ? dataEl.GetString() : null;
                if (!string.IsNullOrEmpty(mimeType) && !string.IsNullOrEmpty(data))
                    image = (mimeType, data);
            }

            Response.ContentType = "text/event-stream";
            Response.Headers.Append("Cache-Control", "no-cache");
            Response.Headers.Append("x-flow", $"{ClassroomFaqFlowIndex}");

            await foreach (var chunk in _classroomFaqService.QueryStreamAsync(inputValue, history, image))
            {
                var payload = JsonSerializer.Serialize(new
                {
                    delta = chunk.Delta,
                    source = chunk.Source,
                    done = chunk.Done,
                    error = chunk.Error,
                });
                await Response.WriteAsync($"data: {payload}\n\n");
                await Response.Body.FlushAsync();
            }

            return new EmptyResult();
        }
    }
}

