        /// <param name="qa"></param>
        /// <returns></returns>
        bool AddQa(Qa qa);

        /// <summary>
        /// 修改問題描述
        /// </summary>
        /// <param name="qa"></param>
        /// <returns></returns>
        bool UpdateQa(Qa qa);

