        /// <param name="page"></param>
        /// <returns></returns>
        (int totalCount, IEnumerable<Qa_category> data) GetQa_categoryList(int pageSize, int page);

        /// <summary>
        /// 新增問題類別
        /// </summary>
        /// <param name="qa_category"></param>
        /// <returns></returns>
        bool AddQa_category(Qa_category qa_category);

        /// <summary>
        /// 修改問題類別
        /// </summary>
        /// <param name="cid"></param>
        /// <param name="cname"></param>
        /// <param name="update_by"></param>
        /// <returns></returns>
        bool UpdateQa_category(Qa_category qa_category);

        /// <summary>
        /// 取得所有問題類別
        /// </summary>
        IEnumerable<Qa_category> GetQa_categoryListAll();

        /// <summary>
        /// 取得探索紀錄，呼叫端要自行核對 account_name 是不是目前登入的使用者。
        /// </summary>
        Exploration? GetExplorationById(Guid id);

