        /// 取得某個帳號的所有探索紀錄，依更新時間新到舊排序。
        /// </summary>
        IEnumerable<Exploration> GetExplorationListForAccount(string accountName);

        /// <summary>
        /// 後台管理用：依帳號彙總探索紀錄統計，支援帳號模糊搜尋、分頁。
