        (int totalCount, IEnumerable<Exploration> data) GetExplorationListByAccount(int pageSize, int page, string accountName, string status);

        bool AddExploration(Exploration exploration);

        /// <summary>
        /// 只更新 history_json（AI 對話的權威狀態）。
        /// </summary>
        bool UpdateExplorationHistory(Guid id, string accountName, string historyJson, DateTime updateDate);

        /// <summary>
        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位。
        /// </summary>
        bool UpdateExplorationDerived(
            Guid id,
            string accountName,
            string? answersJson,
            string? summaryJson,
            string? cardJson,
            string? fastJson,
            string status,
            DateTime updateDate);

        bool DeleteExploration(Guid id, string accountName, DateTime updateDate);

        /// <summary>
        /// 取得某個帳號目前擁有的模組代碼清單，不含總管理者（總管理者不受這張表限制）。
        /// </summary>
        IEnumerable<string> GetModulesForAccount(string accountName);

        /// <summary>
        /// 取得目前所有帳號的模組授權，key 為 account_name，供權限管理頁一次撈全部。
