        Dictionary<string, List<string>> GetAllAccountModules();

        /// <summary>
        /// 整批覆蓋某帳號的模組授權。
        /// </summary>
        bool SetModulesForAccount(string accountName, IEnumerable<string> moduleCodes, string operatorAccountName);
    }
}

