        /// 取得所有問題類別
        /// </summary>
        public IEnumerable<Qa_category> GetQa_categoryListAll()
        {
            var result = _qaCategoryDAO.GetQa_categoryList(99999, 1);
            return result.data;
        }

        /// <summary>
        /// 新增問題類別
        /// </summary>
        /// <param name="qa_category"></param>
        /// <returns></returns>
        public bool AddQa_category(Qa_category qa_category)
        {
            return _qaCategoryDAO.AddQa_category(qa_category);
        }

        /// <summary>
        /// 修改問題類別
        /// </summary>
        /// <param name="qa_category"></param>
        /// <returns></returns>
        public bool UpdateQa_category(Qa_category qa_category)
        {
            return _qaCategoryDAO.UpdateQa_category(qa_category);
        }

        /// <summary>
        /// 取得探索紀錄，呼叫端要自行核對 account_name 是不是目前登入的使用者。
        /// </summary>
        public Exploration? GetExplorationById(Guid id)
        {
            return _explorationDAO.GetExplorationById(id);
        }

        /// <summary>
        /// 取得某個帳號的所有探索紀錄，依更新時間新到舊排序。
        /// </summary>
        public IEnumerable<Exploration> GetExplorationListForAccount(string accountName)
        {
            return _explorationDAO.GetExplorationListForAccount(accountName);
        }

        /// <summary>
        /// 後台管理用：依帳號彙總探索紀錄統計，支援帳號模糊搜尋、分頁。
        /// </summary>
        public (int totalCount, IEnumerable<ExplorationAccountSummary> data) GetExplorationAccountSummaryList(int pageSize, int page, string accountName)
        {
            return _explorationDAO.GetExplorationAccountSummaryList(pageSize, page, accountName);
        }

        /// <summary>
        /// 後台管理用：查詢單一帳號（精準比對）的探索紀錄，支援狀態篩選、分頁。
        /// </summary>
        public (int totalCount, IEnumerable<Exploration> data) GetExplorationListByAccount(int pageSize, int page, string accountName, string status)
        {
            return _explorationDAO.GetExplorationListByAccount(pageSize, page, accountName, status);
        }

        public bool AddExploration(Exploration exploration)
        {
            return _explorationDAO.AddExploration(exploration);
        }

        /// <summary>
        /// 只更新 history_json（AI 對話的權威狀態）。
        /// </summary>
        public bool UpdateExplorationHistory(Guid id, string accountName, string historyJson, DateTime updateDate)
        {
            return _explorationDAO.UpdateExplorationHistory(id, accountName, historyJson, updateDate);
        }

        /// <summary>
        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位。
        /// </summary>
        public bool UpdateExplorationDerived(
            Guid id,
            string accountName,
            string? answersJson,
            string? summaryJson,
            string? cardJson,
            string? fastJson,
            string status,
            DateTime updateDate)
        {
            return _explorationDAO.UpdateExplorationDerived(id, accountName, answersJson, summaryJson, cardJson, fastJson, status, updateDate);
        }

        public bool DeleteExploration(Guid id, string accountName, DateTime updateDate)
        {
            return _explorationDAO.DeleteExploration(id, accountName, updateDate);
        }

        /// <summary>
        /// 取得某個帳號目前擁有的模組代碼清單，不含總管理者（總管理者不受這張表限制）。
        /// </summary>
        public IEnumerable<string> GetModulesForAccount(string accountName)
        {
            return _adminPermissionDAO.GetModulesForAccount(accountName);
        }

        /// <summary>
        /// 取得目前所有帳號的模組授權，key 為 account_name，供權限管理頁一次撈全部。
        /// </summary>
        public Dictionary<string, List<string>> GetAllAccountModules()
        {
            return _adminPermissionDAO.GetAllGranted()
                .GroupBy(x => x.account_name)
                .ToDictionary(g => g.Key, g => g.Select(x => x.module_code).ToList());
        }

        /// <summary>
        /// 整批覆蓋某帳號的模組授權。
        /// </summary>
        public bool SetModulesForAccount(string accountName, IEnumerable<string> moduleCodes, string operatorAccountName)
        {
            return _adminPermissionDAO.SetModulesForAccount(accountName, moduleCodes, operatorAccountName);
        }
    }
}

using chatai.Adapter.Chatai.DTO;
using chatai.Core.Models.request.Exploration;
using chatai.Core.Models.reponse.Exploration;
using chatai.Core.Module;
using chatai_admin.Controllers.Base;
using Microsoft.AspNetCore.Mvc;
using ntu.Common.Utility.Exception;
using ntu.Common.Utility.Helper;

namespace chatai_admin.Controllers
{
    /// <summary>
    /// flowId=7（學習規劃探索助手）的使用紀錄查詢／維護，跟 QA 管理完全獨立。
    /// [AdminModule] 對應「學規AI小助手紀錄」選單，ValidateJWTFilter 會依此檢查呼叫者的模組權限
    /// （總管理者不受限）。
    /// </summary>
    [Route("api/[controller]/[action]")]
    [chatai_admin.Attribute.AdminModule("exploration")]
    public class ExplorationController : BaseApiController
    {
        private readonly IChataiModule _chataiModule;

        public ExplorationController(IChataiModule chataiModule)
        {
            _chataiModule = chataiModule;
        }

        [HttpPost]
        public IActionResult SearchAccounts([FromBody] SearchAccountRequest request)
        {
            var model = new SearchAccountResponse();

            var result = _chataiModule.GetExplorationAccountSummaryList(request.page_size, request.page, request.account_name);

            model.Items = result.data;
            model.TotalCount = result.totalCount;

            return Ok(model);
        }

        [HttpPost]
        public IActionResult Search([FromBody] SearchRequest request)
        {
            var model = new SearchResponse();

            var result = _chataiModule.GetExplorationListByAccount(request.page_size, request.page, request.account_name, request.status);

            var items = AutoMapperHelper.MapList<Exploration, SearchResponse.ExplorationResponse>(result.data.ToList());

            items.ForEach(x =>
            {
                x.duration_seconds = x.status == "completed"
                    ? (x.update_date - x.create_date).TotalSeconds
                    : null;
            });

            model.Items = items;
            model.TotalCount = result.totalCount;

            return Ok(model);
        }

        [HttpPost]
        public IActionResult Delete([FromBody] DeleteRequest request)
        {
            var result = _chataiModule.DeleteExploration(request.id, request.account_name, DateTime.Now);

            if (!result)
                throw new CustomException("刪除失敗，請重新再試");

            return Ok();
        }
    }
}

