import { Role } from "@/lib/enum";
import { TokenKey } from "@/lib/constant";
import { JwtPayload } from "jwt-decode";
export interface QAItem {
  id: number;
  cid: number;
  type: "organizer" | "qa";
  question: string;
  answer: string;
  tel?: string;
  email?: string;
}

export enum MessageStatus {
  User = "user",
  Pending = "pending",
  Receiving = "receiving",
  End = "end",
  Error = "error",
}

export type MessageContact = {
  name?: string;
  tel?: string;
  email?: string;
};

export type Message = {
  role: Role;
  content: string;
  timestamp: number;
  status: MessageStatus;
  source?: string;
  contact?: MessageContact[];
  qa?: QAItem[];
  question?: string;
};

export enum DataType {
  Ready = "ready",
  Close = "close",
  ToggleFullscreen = "toggle-fullscreen",
  Resize = "resize",
}

export type FromIframeData =
  | { type: DataType.ToggleFullscreen; value: boolean }
  | { type: DataType.Close }
  | { type: DataType.Ready };

export type ToIframeData = {
  type: DataType.Resize;
  width: number;
};

export type JwtToken = JwtPayload & {
  [TokenKey.CHINESE_NAME]: string;
  [TokenKey.ACCOUNT_NAME]: string;
  [TokenKey.ACCOUNT_TYPE]: string;
};

export type Locale = 'zh-TW' | 'en'
export type MotionMode = 'system' | 'full' | 'reduced'

export type TopicKey =
  | 'academics'
  | 'course-selection'
  | 'career'
  | 'time-management'
  | 'motivation'
  | 'other'

export interface Settings {
  locale: Locale
  motionMode: MotionMode
  studentName: string
  /** 打字機每字間隔（毫秒/字）；動態關閉時不生效 */
  typingSpeedMs: number
}

export interface Answer {
  questionIndex: number
  text: string
  updatedAt: string
  /**
   * 真實對話模式下，這題實際的反映／提問文字是 AI 當輪動態產生的，不是固定題庫；
   * 從 AdvisingChatService 的回覆解析失敗時兩者都留空，畫面退回顯示 rawReply。
   */
  reflection?: string
  question?: string
  /** 解析失敗時的原始 AI 回覆全文，供畫面兜底顯示，避免解析失敗時開天窗 */
  rawReply?: string
}

export interface SummarySection {
  key: 'issue' | 'status' | 'strengths' | 'directions' | 'resources' | 'raw'
  title: string
  /** 純文字內容：畫面段落與匯出報告共用 */
  body: string
  /** 條列呈現時的項目（設計稿中「優勢與資源」「可能的探索方向」為條列） */
  items?: string[]
  /** 以資源卡呈現時的推薦資源 */
  resources?: RecommendedResource[]
}

/**
 * AdvisingChatService Stage 1.5 的 FAST Model 六題自評結果。
 * scores 在使用者填完六題自評當下就有了；directionScore/resourceScore/quadrant/advice
 * 要等 Stage 3 總結報告解析出來才補上，所以都是可選欄位。
 */
export interface FastAssessment {
  /** 1~6 分，依序對應六句自評問句 */
  scores: number[]
  directionScore?: number
  resourceScore?: number
  quadrant?: 1 | 2 | 3 | 4
  /** Stage 3 報告裡對應象限的一段固定探索建議文字 */
  advice?: string
}

/** 對應 chatai_backend RunController body.history 的單輪對話紀錄 */
export interface ConversationTurn {
  role: 'user' | 'model'
  text: string
}

export interface RecommendedResource {
  name: string
  type: string
  url: string
  reason: string
  /** 自我察覺卡頁尾使用的簡稱；未提供時退回 name */
  shortName?: string
}

export interface SelfAwarenessCard {
  topicLabel: string
  date: string
  coreInsight: string
  nextExplorationDirection: string
  /** 卡面上的關鍵字標籤（設計稿為 3 個 # 標籤） */
  keywords?: string[]
  resources: RecommendedResource[]
}

export type ExplorationStatus = 'in-progress' | 'completed'

export interface Exploration {
  id: string
  topic: TopicKey
  topicCustomLabel?: string
  answers: Answer[]
  summary?: SummarySection[]
  card?: SelfAwarenessCard
  status: ExplorationStatus
  createdAt: string
  updatedAt: string
  /**
   * 真實對話模式下的完整多輪對話紀錄，每次呼叫 API 都要整包帶入（後端沒有 session）。
   * 沒有這份資料就無法在重新整理頁面後接續對話，所以要跟其他欄位一起存進 localStorage。
   */
  history?: ConversationTurn[]
  fast?: FastAssessment
}

import type { TopicKey } from '@/types'

export interface TopicOption {
  key: TopicKey
  labelKey: string
  descKey: string
}

/** 卡片式議題（設計稿為 5 張卡 + 一列「其他」自訂主題） */
export const TOPIC_CARDS: TopicOption[] = [
  { key: 'academics', labelKey: 'topics.academics', descKey: 'topics.academicsDesc' },
  { key: 'course-selection', labelKey: 'topics.courseSelection', descKey: 'topics.courseSelectionDesc' },
  { key: 'career', labelKey: 'topics.career', descKey: 'topics.careerDesc' },
  { key: 'time-management', labelKey: 'topics.timeManagement', descKey: 'topics.timeManagementDesc' },
  { key: 'motivation', labelKey: 'topics.motivation', descKey: 'topics.motivationDesc' }
]

export const OTHER_TOPIC: TopicOption = {
  key: 'other',
  labelKey: 'topics.other',
  descKey: 'topics.otherDesc'
}

/** 含「其他」的完整清單，供議題標籤查詢使用 */
export const TOPICS: TopicOption[] = [...TOPIC_CARDS, OTHER_TOPIC]

