// ==================== flow=9（學習規劃探索助手，聊天式 UI）====================
// 跟 apps/explore（flow=7 沉浸式體驗）共用同一個後端 AdvisingChatService／同一張 exploration
// 表，差別只在建立紀錄時的 channel（'chat' vs 'explore'）與前端呈現方式。這裡複製了
// apps/explore 的「選題 → exploration_id 持久化 → Stage2/3 解析＋PATCH」邏輯，因為兩個前端
// app 各自獨立打包、無法互相 import（見規劃文件）。

/** AdvisingChatService 固定跑 10 題（見 AdvisingChatService.cs Stage 2）。 */
const TOTAL_QUESTIONS = 10;

const advisingExplorationId = ref<string | null>(null);
const advisingState = ref<"idle" | "selecting-topic" | "active">("idle");
const advisingTopicLabel = ref("");
const advisingDerived = ref<{
  answers: Answer[];
  summary?: SummarySection[];
  card?: SelfAwarenessCard;
  fast?: FastAssessment;
  status: ExplorationStatus;
}>({ answers: [], status: "in-progress" });

function advisingTopicLabelOf(topic: string, customLabel?: string): string {
  if (customLabel) return customLabel;
  return ADVISING_TOPICS.find((o) => o.key === topic)?.label ?? ADVISING_OTHER_TOPIC.label;
}

// 跟上面開場白的 watch 分開處理：flow=9 進頁面時要先去資料庫查有沒有未完成的紀錄可以續接，
// 是非同步的，跟其他 flow「同步塞一句開場白」的邏輯放在一起會混淆。
watch(
  () => route.query.flow,
  async (flow) => {
    if (flow?.toString() !== "9" || advisingState.value !== "idle") return;

    const record = await findInProgress().catch((err) => {
      console.error("[ChatProvider] findInProgress failed", err);
      return null;
    });

    if (record) {
      advisingExplorationId.value = record.id;
      advisingTopicLabel.value = advisingTopicLabelOf(record.topic, record.topicCustomLabel);
      advisingDerived.value = {
        answers: record.answers,
        summary: record.summary,
        card: record.card,
        fast: record.fast,
        status: record.status,
      };
      messages.value = (record.history ?? []).map((turn) => [
        {
          role: turn.role === "user" ? Role.User : Role.Assistant,
          content: turn.text,
          timestamp: Date.now(),
          status: Status.End,
        },
      ]);
      advisingState.value = "active";
    } else {
      advisingState.value = "selecting-topic";
    }
  },
  { immediate: true },
);

async function startAdvisingTopic(topic: string, customLabel?: string) {
  if (advisingState.value === "active") return;

  const label = advisingTopicLabelOf(topic, customLabel);
  const record = await createExploration({ topic: topic as TopicKey, topicCustomLabel: customLabel });

  advisingExplorationId.value = record.id;
  advisingTopicLabel.value = label;
  advisingDerived.value = { answers: [], status: "in-progress" };
  messages.value.push([
    {
      role: Role.Assistant,
      content: ADVISING_OPENING_MESSAGE,
      timestamp: Date.now(),
      status: Status.End,
    },
  ]);
  advisingState.value = "active";

  await send(label);
}

/**
 * 非預期格式（不是新一題、不是總結報告、也不是 FAST 自評提示）——多半是 Stage 2 期間解析失敗，
 * 用原始文字頂著一個新題目卡位，至少不讓畫面開天窗。10 題都已經有紀錄時不套用，避免生出
 * 不存在的「第 11 題」（邏輯跟 apps/explore 的 useAdvisingConversation.ts 一致）。
 */
function buildAdvisingFallbackAnswers(reply: string): Answer[] | undefined {
  if (advisingDerived.value.answers.length >= TOTAL_QUESTIONS) {
    console.warn("[ChatProvider] reply after all questions were answered did not match final report format", reply);
    return undefined;
  }
  const answers = [...advisingDerived.value.answers];
  answers.push({
    questionIndex: answers.length,
    text: "",
    updatedAt: new Date().toISOString(),
    rawReply: reply,
  });
  return answers;
}

function applyAdvisingStage2Reply(
  stage2: NonNullable<ReturnType<typeof parseStage2Reply>>,
  reply: string,
): Answer[] {
  const answers = [...advisingDerived.value.answers];
  const idx = answers.findIndex((a) => a.questionIndex === stage2.questionNumber - 1);
  const entry: Answer = {
    questionIndex: stage2.questionNumber - 1,
    text: answers[idx]?.text ?? "",
    updatedAt: new Date().toISOString(),
    reflection: stage2.reflection,
    question: stage2.question,
    rawReply: reply,
  };
  if (idx >= 0) answers[idx] = { ...answers[idx], ...entry };
  else answers.push(entry);
  return answers;
}

function applyAdvisingFinalReport(reply: string): Partial<typeof advisingDerived.value> {
  const parsed = parseStage3Report(reply);
  const summary = parsed?.summary ?? [{ key: "raw" as const, title: "總結報告", body: reply }];
  const patch: Partial<typeof advisingDerived.value> = {
    summary,
    card: {
      topicLabel: advisingTopicLabel.value,
      date: new Date().toISOString().slice(0, 10),
      ...buildSelfAwarenessCard(advisingTopicLabel.value, summary),
    },
    status: "completed",
  };
  // flow=9 沒有獨立的 FAST 六題自評畫面（見 apps/explore 的 FastAssessmentPage），六個原始分數
  // 不會提前存在 advisingDerived.fast 裡，所以這裡不像 apps/explore 那樣要求 current.fast 已存在
  // 才合併，只要 Stage 3 有解析出象限/建議就先存，scores 留空。
  if (parsed?.fast) {
    patch.fast = { ...(advisingDerived.value.fast ?? { scores: [] }), ...parsed.fast };
  }
  return patch;
}

async function persistAdvisingDerived(patch: Partial<typeof advisingDerived.value>, rethrow: boolean) {
  if (!advisingExplorationId.value) return;
  try {
    await updateExplorationDerived(advisingExplorationId.value, {
      answers: patch.answers ?? advisingDerived.value.answers,
      summary: patch.summary ?? advisingDerived.value.summary,
      card: patch.card ?? advisingDerived.value.card,
      fast: patch.fast ?? advisingDerived.value.fast,
      status: patch.status ?? advisingDerived.value.status,
    });
  } catch (err) {
    console.error("[ChatProvider] persist advising derived fields failed", err);
    if (rethrow) throw err;
  }
}

/** flow=9 的送出邏輯：後端對話紀錄由 exploration_id 管理，回覆解析＋PATCH 邏輯照抄 apps/explore。 */
async function sendAdvisingExplorationMessage(content: string) {
  const messageIndex = addUserMessage(content);
  await callAIWrapper(messageIndex, content, "9", undefined, undefined, advisingExplorationId.value ?? undefined);

  const replyMessage = messages.value[messageIndex][1];
  if (!replyMessage || replyMessage.status === Status.Error) return;
  const reply = replyMessage.content;

  let patch: Partial<typeof advisingDerived.value> = {};
  let isFinal = false;

  const stage2 = parseStage2Reply(reply);
  if (stage2) {
    patch.answers = applyAdvisingStage2Reply(stage2, reply);
  } else if (isFinalReport(reply)) {
    isFinal = true;
    patch = { ...patch, ...applyAdvisingFinalReport(reply) };
  } else if (!isFastAssessmentPrompt(reply) && (advisingDerived.value.fast?.scores?.length ?? 0) > 0) {
    const fallbackAnswers = buildAdvisingFallbackAnswers(reply);
    if (fallbackAnswers) patch.answers = fallbackAnswers;
  }

  advisingDerived.value = { ...advisingDerived.value, ...patch };
  await persistAdvisingDerived(patch, isFinal);
}

