// ==================== 使用者訊息創建 ====================

function addUserMessage(content: string): number {
  const timestamp = Date.now();
  const length = messages.value.length;

  messages.value.push([]);
  messages.value[length][0] = {
    role: Role.User,
    content,
    timestamp,
    status: Status.User,
  };
  toChatBottom({ behavior: "smooth" });

  return length;
}

// ==================== 主要流程 ====================

async function send(content: string, flowId?: string) {
  // 1. 創建用戶消息（附加照片時在訊息內容加註提示，讓歷史紀錄也看得出來曾經附圖）
  const pendingImage = attachedImage.value ?? undefined;
  const displayContent = pendingImage ? `${content}\n📎 已附加照片` : content;
  const messageIndex = addUserMessage(displayContent);
  clearAttachedImage();

  // flow=3（簡易模式）或 flow=6（Gemini File Search RAG）時，跳過 QA 搜尋，直接呼叫 AI
  const routeFlow = route.query.flow?.toString();
  if (routeFlow && SIMPLE_MODE_FLOW_IDS.includes(routeFlow)) {
    await callAIWrapper(messageIndex, content, routeFlow, undefined, pendingImage);
    return;
  }

  // 2. 搜索 QA
  const qaResults = await searchQA(content);
  // 3. 處理 QA 結果
  const shouldShowQAList = handleQAResults(qaResults, messageIndex, content);

