1	<script setup lang="ts">
2	import { inject, Ref, ref, watch, nextTick, onUnmounted, onMounted } from "vue";
3	import { Button } from "@/components/ui/button";
4	import { useQACategory } from "@/hooks/useQACategory";
5	import { useQADesc, type QADesc } from "@/hooks/useQADesc";
6	import type { QAItem } from "@/lib/type";
7	import { ChevronLeft, ChevronRight } from "lucide-vue-next";
8	import { cn } from "@/lib/utils";
9	
10	const activeTab = ref<string>("");
11	const questionsContainer = ref<HTMLDivElement | null>(null);
12	const showFade = ref(false);
13	const tabsContainer = ref<HTMLDivElement | null>(null);
14	const showLeftButton = ref(false);
15	const showRightButton = ref(false);
16	
17	const send = inject<Function>("send");
18	const sendDirectAnswer = inject<(qa: QAItem) => void>("sendDirectAnswer");
19	const isPending = inject<Ref<boolean>>("isPending");
20	
21	const { data: tabs } = useQACategory();
22	const { data: questions, isLoading: isLoadingQuestions } = useQADesc(activeTab);
23	
24	// 保存上一個 tab 的問題列表，用於在載入時顯示
25	const previousQuestions = ref<QADesc[]>([]);
26	
27	// 顯示的問題列表：載入時顯示舊資料，載入完成後顯示新資料
28	const displayQuestions = ref<QADesc[]>([]);
29	
30	// 檢查是否需要顯示漸層和滾動
31	function checkShowFade() {
32	  if (!questionsContainer.value) {
33	    showFade.value = false;
34	    return;
35	  }
36	  const container = questionsContainer.value;
37	  const scrollDiff = container.scrollHeight - container.clientHeight;
38	  // 只有當高度差超過 10px 時才認為需要滾動（避免微小位移）
39	  const hasScroll = scrollDiff > 10;
40	
41	  // 計算距離底部的距離
42	  const distanceToBottom =
43	    container.scrollHeight - container.scrollTop - container.clientHeight;
44	  // 當距離底部小於等於 5px 時，認為已經到底部
45	  const isAtBottom = distanceToBottom <= 5;
46	
47	  // 只有在有滾動且不在底部時才顯示漸層
48	  showFade.value = hasScroll && !isAtBottom;
49	
50	  // 根據是否需要滾動來設置 overflow
51	  if (hasScroll) {
52	    container.style.overflowY = "auto";
53	  } else {
54	    container.style.overflowY = "hidden";
55	    // 確保滾動位置重置
56	    container.scrollTop = 0;
57	  }
58	}
59	
60	// 更新顯示問題列表並處理高度過渡
61	async function updateDisplayQuestions(newQuestions: QADesc[]) {
62	  if (!questionsContainer.value) {
63	    displayQuestions.value = newQuestions;
64	    return;
65	  }
66	
67	  const container = questionsContainer.value;
68	  const MAX_HEIGHT = 180; // 與 CSS 中的 max-height 保持一致
69	
70	  // 先重置滾動位置到頂部（與列表更新同時進行）
71	  container.scrollTop = 0;
72	
73	  // 記錄更新前的高度（取實際高度和最大高度的較小值）
74	  const oldScrollHeight = container.scrollHeight;
75	  const oldHeight = Math.min(oldScrollHeight, MAX_HEIGHT);
76	
77	  // 更新問題列表（與滾動重置同時進行）
78	  displayQuestions.value = newQuestions;
79	
80	  // 等待 DOM 更新
81	  await nextTick();
82	  await new Promise((resolve) => requestAnimationFrame(resolve));
83	
84	  // 計算新高度（取實際高度和最大高度的較小值）
85	  const newScrollHeight = container.scrollHeight;
86	  const newHeight = Math.min(newScrollHeight, MAX_HEIGHT);
87	
88	  // 檢查是否需要顯示漸層
89	  checkShowFade();
90	
91	  // 如果高度不同，執行過渡動畫
92	  if (oldHeight !== newHeight) {
93	    container.style.height = `${oldHeight}px`;
94	    container.style.transition = "height 0.3s ease-in-out";
95	
96	    // 強制重排
97	    container.offsetHeight;
98	
99	    // 設置新高度觸發過渡
100	    requestAnimationFrame(() => {
101	      container.style.height = `${newHeight}px`;
102	
103	      // 過渡完成後設置為 auto（會受 max-height 限制）
104	      setTimeout(() => {
105	        container.style.height = "auto";
106	        container.style.transition = "";
107	        checkShowFade();
108	      }, 300);
109	    });
110	  } else {
111	    // 即使高度相同，也要確保樣式正確
112	    container.style.height = "auto";
113	    checkShowFade();
114	  }
115	}
116	
117	// 當問題資料更新時，更新顯示的問題列表
118	watch(
119	  [questions, isLoadingQuestions],
120	  async ([newQuestions, isLoading]) => {
121	    const questionsList = newQuestions || [];
122	    if (!isLoading) {
123	      // 載入完成後，更新顯示的問題列表（會觸發高度過渡）
124	      if (questionsList.length > 0) {
125	        await updateDisplayQuestions(questionsList);
126	        previousQuestions.value = questionsList;
127	      } else {
128	        await updateDisplayQuestions([]);
129	        if (previousQuestions.value.length === 0) {
130	          previousQuestions.value = [];
131	        }
132	      }
133	    } else {
134	      // 開始載入時，如果有舊資料就保留，否則清空
135	      if (previousQuestions.value.length > 0) {
136	        displayQuestions.value = previousQuestions.value;
137	      } else {
138	        displayQuestions.value = [];
139	      }
140	    }
141	  },
142	  { immediate: true },
143	);
144	
145	watch(
146	  tabs,
147	  (newTabs) => {
148	    const tabsList = newTabs || [];
149	    if (tabsList.length > 0 && !activeTab.value) {
150	      activeTab.value = tabsList[0].value;
151	    }
152	    // tabs 更新後檢查滾動邊界
153	    nextTick(() => {
154	      checkTabsScroll();
155	    });
156	  },
157	  { immediate: true },
158	);
159	
160	// 監聽 tabs 容器滾動
161	watch(
162	  tabsContainer,
163	  (container) => {
164	    if (container) {
165	      container.addEventListener("scroll", checkTabsScroll);
166	      // 初始檢查
167	      nextTick(() => {
168	        checkTabsScroll();
169	      });
170	    }
171	  },
172	  { immediate: true },
173	);
174	
175	// 監聽滾動事件
176	watch(
177	  questionsContainer,
178	  (container) => {
179	    if (container) {
180	      container.addEventListener("scroll", checkShowFade);
181	      checkShowFade();
182	    }
183	  },
184	  { immediate: true },
185	);
186	
187	onMounted(() => {
188	  // 監聽窗口大小變化，重新檢查滾動邊界
189	  window.addEventListener("resize", checkTabsScroll);
190	});
191	
192	onUnmounted(() => {
193	  if (questionsContainer.value) {
194	    questionsContainer.value.removeEventListener("scroll", checkShowFade);
195	  }
196	  if (tabsContainer.value) {
197	    tabsContainer.value.removeEventListener("scroll", checkTabsScroll);
198	  }
199	  window.removeEventListener("resize", checkTabsScroll);
200	});
201	
202	function setActiveTab(tab: string) {
203	  activeTab.value = tab;
204	}
205	
206	function onSend(question: QADesc) {
207	  if (!send || !isPending || !sendDirectAnswer) return;
208	  if (isPending.value) return;
209	
210	  sendDirectAnswer(question);
211	}
212	
213	// 檢查 tabs 滾動邊界，控制按鈕顯示
214	function checkTabsScroll() {
215	  if (!tabsContainer.value) {
216	    showLeftButton.value = false;
217	    showRightButton.value = false;
218	    return;
219	  }
220	  const container = tabsContainer.value;
221	  const scrollLeft = container.scrollLeft;
222	  const scrollWidth = container.scrollWidth;
223	  const clientWidth = container.clientWidth;
224	
225	  // 檢查是否在左邊界（允許 1px 誤差）
226	  showLeftButton.value = scrollLeft > 1;
227	
228	  // 檢查是否在右邊界（允許 1px 誤差）
229	  showRightButton.value = scrollLeft < scrollWidth - clientWidth - 1;
230	}
231	
232	// 滑動 tabs 容器
233	function scrollTabs(direction: "left" | "right") {
234	  if (!tabsContainer.value) return;
235	
236	  const container = tabsContainer.value;
237	  const scrollAmount = container.clientWidth * 0.5; // 滑動 50% 的寬度
238	
239	  if (direction === "left") {
240	    container.scrollBy({
241	      left: -scrollAmount,
242	      behavior: "smooth",
243	    });
244	  } else {
245	    container.scrollBy({
246	      left: scrollAmount,
247	      behavior: "smooth",
248	    });
249	  }
250	}
251	</script>
252	
253	<template>
254	  <div
255	    v-if="tabs && tabs.length > 0"
256	    class="border-input/30 bg-background/30 my-4 space-y-3 rounded-2xl border p-3 backdrop-blur-sm"
257	  >
258	    <div class="flex items-center gap-4 whitespace-nowrap">
259	      <p class="ml-1 shrink-0 text-lg font-semibold">快速找到承辦單位</p>
260	      <div class="relative min-w-0 flex-1">
261	        <div
262	          ref="tabsContainer"
263	          class="scrollbar-hide flex w-full flex-nowrap items-center gap-2 overflow-x-auto overflow-y-hidden scroll-smooth"
264	        >
265	          <Button
266	            v-for="tab in tabs"
267	            :key="tab.value"
268	            :variant="activeTab === tab.value ? 'default' : 'outline'"
269	            class="shrink-0 rounded-full px-4 py-1.5"
270	            :class="
271	              activeTab === tab.value
272	                ? 'shadow-primary-button'
273	                : 'text-muted-foreground active:text-primary-foreground border-none bg-white active:bg-[#262626]'
274	            "
275	            @click="setActiveTab(tab.value)"
276	          >
277	            {{ tab.label }}
278	          </Button>
279	        </div>
280	        <Button
281	          variant="outline"
282	          size="icon"
283	          :class="
284	            cn(
285	              'bg-background/80 hover:bg-background absolute top-1/2 left-0 z-10 size-9 -translate-y-1/2 rounded-full shadow-md backdrop-blur-sm transition-opacity duration-200',
286	              showLeftButton ? 'opacity-100' : 'pointer-events-none opacity-0',
287	            )
288	          "
289	          @click="scrollTabs('left')"
290	        >
291	          <ChevronLeft class="h-4 w-4" />
292	        </Button>
293	        <Button
294	          variant="outline"
295	          size="icon"
296	          :class="
297	            cn(
298	              'bg-background/80 hover:bg-background absolute top-1/2 right-0 z-10 size-9 -translate-y-1/2 rounded-full shadow-md backdrop-blur-sm transition-opacity duration-200',
299	              showRightButton ? 'opacity-100' : 'pointer-events-none opacity-0',
300	            )
301	          "
302	          @click="scrollTabs('right')"
303	        >
304	          <ChevronRight class="h-4 w-4" />
305	        </Button>
306	      </div>
307	    </div>
308	    <div class="questions-wrapper">
309	      <div
310	        ref="questionsContainer"
311	        class="questions-container"
312	        :class="{ 'has-fade': showFade }"
313	      >
314	        <div class="flex flex-col gap-2 transition-opacity duration-200">
315	          <template v-if="displayQuestions.length === 0 && !isLoadingQuestions">
316	            <div
317	              class="text-muted-foreground flex items-center justify-center py-4"
318	            >
319	              暫無問題
320	            </div>
321	          </template>
322	          <template v-else-if="displayQuestions.length > 0">
323	            <Button
324	              v-for="(question, index) in displayQuestions"
325	              :key="`${question.cid}-${question.id}`"
326	              variant="outline"
327	              @click="onSend(question)"
328	              class="justify-start text-left whitespace-normal"
329	            >
330	              <span
331	                class="animate-in fade-in-0 slide-in-from-right-2 fill-mode-backwards duration-300"
332	                :style="{
333	                  animationDelay: `${index * 100}ms`,
334	                }"
335	              >
336	                {{ question.question }}
337	              </span>
338	            </Button>
339	          </template>
340	        </div>
341	      </div>
342	    </div>
343	  </div>
344	</template>
345	
346	<style scoped>
347	.scrollbar-hide {
348	  scrollbar-width: none; /* Firefox */
