using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace chatai.Adapter.Chatai.Common
{
    public class DBConfig
    {
        private static string? _connString = string.Empty;

        private static IServiceProvider? _serviceProvider;

        /// <summary>
        /// 於 Program 注入 IServiceProvider
        /// </summary>
        /// <param name="serviceProvider"></param>
        public static void Configure(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider;
        }

        private static IConfiguration? Configuration => _serviceProvider!.GetService<IConfiguration>();

        private static string GetConnection(string name) => Configuration!.GetConnectionString(name)!;

        /// <summary>
        /// 資料庫連線字串
        /// </summary>
        public static string ConnString
        {
            get
            {
                if (string.IsNullOrEmpty(_connString))
                {
                    _connString = GetConnection("DB_198_Chatai_Connection");
                    if (string.IsNullOrEmpty(_connString)) throw new ArgumentNullException($"DB_198_Chatai_Connection is not setting.");
                }

                return _connString;
            }
        }

    }
}

