import type { Exploration, TopicKey } from '@/types'
import { STORAGE_KEYS } from './keys'

interface CreateInput {
  topic: TopicKey
  topicCustomLabel?: string
}

function readAll(): Exploration[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.explorations)
    if (!raw) return []
    return JSON.parse(raw) as Exploration[]
  } catch {
    return []
  }
}

function writeAll(list: Exploration[]): void {
  try {
    localStorage.setItem(STORAGE_KEYS.explorations, JSON.stringify(list))
  } catch {
    // localStorage unavailable (quota exceeded, private mode) — fail silently for this demo
  }
}

function generateId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function listExplorations(): Exploration[] {
  const all = readAll()
  return [...all].sort((a, b) =>
    new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
  )
}

export function getExploration(id: string): Exploration | null {
  return readAll().find(r => r.id === id) ?? null
}

export function createExploration(input: CreateInput): Exploration {
  const now = new Date().toISOString()
  const record: Exploration = {
    id: generateId(),
    topic: input.topic,
    topicCustomLabel: input.topicCustomLabel,
    answers: [],
    status: 'in-progress',
    createdAt: now,
    updatedAt: now
  }
  writeAll([...readAll(), record])
  return record
}

export function updateExploration(
  id: string,
  patch: Partial<Omit<Exploration, 'id' | 'createdAt'>>
): Exploration {
  const all = readAll()
  const idx = all.findIndex(r => r.id === id)
  if (idx < 0) throw new Error(`exploration ${id} not found`)
  const updated: Exploration = {
    ...all[idx],
    ...patch,
    // 呼叫端可明確指定 updatedAt（Demo 資料需要回填較早的時間），否則一律更新為現在
    updatedAt: patch.updatedAt ?? new Date().toISOString()
  }
  all[idx] = updated
  writeAll(all)
  return updated
}

export function findInProgress(): Exploration | null {
  return listExplorations().find(r => r.status === 'in-progress') ?? null
}

export function deleteExploration(id: string): void {
  writeAll(readAll().filter(r => r.id !== id))
}

import type { Exploration } from '@/types'
import { createExploration, listExplorations, updateExploration } from '@/storage/explorations'
import { DEMO_QUESTIONS } from './demo-dialogue'
import { DEMO_CARD, DEMO_SUMMARY } from './demo-summary'

/** Demo 用的探索進度樣板 */
export type DemoStage = 'fresh' | 'midway' | 'answered' | 'completed'

const ANSWERED_COUNT: Record<DemoStage, number> = {
  fresh: 0,
  midway: 5,
  answered: DEMO_QUESTIONS.length,
  completed: DEMO_QUESTIONS.length
}

function buildAnswers(count: number, timestamp: string) {
  return DEMO_QUESTIONS.slice(0, count).map(question => ({
    questionIndex: question.index,
    text: question.sampleAnswer,
    updatedAt: timestamp
  }))
}

/**
 * 建立一筆帶有示範內容的探索紀錄，供場景選單直接跳到後段場景時使用。
 * 只寫入 localStorage 的 Demo 資料，不涉及任何真實個資。
 */
export function seedDemoExploration(stage: DemoStage): Exploration {
  const record = createExploration({ topic: 'career' })
  const timestamp = new Date().toISOString()
  const answers = buildAnswers(ANSWERED_COUNT[stage], timestamp)

  if (stage === 'completed') {
    return updateExploration(record.id, {
      answers,
      summary: DEMO_SUMMARY,
      card: { ...DEMO_CARD, date: timestamp.slice(0, 10) },
      status: 'completed'
    })
  }

  return updateExploration(record.id, { answers, status: 'in-progress' })
}

const SAMPLE_HISTORY_TOPICS = [
  { topic: 'career' as const, label: '學習規劃', daysAgo: 8 },
  { topic: 'time-management' as const, label: '時間管理', daysAgo: 30 },
  { topic: 'motivation' as const, label: '生涯探索', daysAgo: 73 }
]

const SAMPLE_HISTORY_INSIGHTS = [
  '把企劃排版的優勢與剛起步的程式能力結合，找到 AI 時代裡屬於自己的獨特位置。',
  '讓我分心的其實不是懶，而是任務太模糊——先把「下一步」寫具體。',
  '發現自己對「把複雜的事說清楚」這件事最有熱情。'
]

const DAY_IN_MS = 24 * 60 * 60 * 1000

/** 一次補上三筆已完成的示範紀錄，方便展示歷史紀錄列表與詳情。 */
export function seedDemoHistory(): Exploration[] {
  const seeded = SAMPLE_HISTORY_TOPICS.map((entry, index) => {
    const created = createExploration({ topic: entry.topic, topicCustomLabel: entry.label })
    const timestamp = new Date(Date.now() - entry.daysAgo * DAY_IN_MS).toISOString()
    return updateExploration(created.id, {
      answers: buildAnswers(DEMO_QUESTIONS.length, timestamp),
      summary: DEMO_SUMMARY,
      card: {
        ...DEMO_CARD,
        topicLabel: entry.label,
        coreInsight: SAMPLE_HISTORY_INSIGHTS[index],
        date: timestamp.slice(0, 10)
      },
      status: 'completed',
      updatedAt: timestamp
    })
  })

  return seeded
}

export function hasStoredExplorations(): boolean {
  return listExplorations().length > 0
}

import { inject, onUnmounted, provide, ref, watch, type InjectionKey, type Ref } from 'vue'
import type { Answer, Exploration, SelfAwarenessCard, SummarySection } from '@/types'
import { getExploration, updateExplorationDerived } from '@/services/explorationApi'
import { useAutosave } from './useAutosave'

interface ExplorationContextValue {
  exploration: Ref<Exploration | null>
  loading: Ref<boolean>
  setAnswer: (questionIndex: number, text: string) => void
  finish: (summary: SummarySection[], card: SelfAwarenessCard) => void
}

const ExplorationKey: InjectionKey<ExplorationContextValue> = Symbol('Exploration')

/**
 * 依 id（可為 route param 的 reactive ref）提供一份探索紀錄的讀寫狀態，answers/summary/card/fast/status
 * 這幾個衍生欄位會自動 debounce PATCH 回後端。history（AI 對話的權威狀態）不在這裡寫，
 * 由 RunController.RunAdvisingExploreFlow 在每輪對話結束後直接存回去（見 useAdvisingConversation.ts）。
 */
export function provideExploration(id: Ref<string>): ExplorationContextValue {
  const exploration = ref<Exploration | null>(null) as Ref<Exploration | null>
  const loading = ref(true)

  async function load(explorationId: string) {
    loading.value = true
    try {
      exploration.value = await getExploration(explorationId)
    } catch (err) {
      console.error('[useExploration] load failed', err)
      exploration.value = null
    } finally {
      loading.value = false
    }
  }

  void load(id.value)

  const { flush } = useAutosave(
    exploration,
    e => {
      if (!e) return
      updateExplorationDerived(e.id, {
        answers: e.answers,
        summary: e.summary,
        card: e.card,
        fast: e.fast,
        status: e.status
      }).catch(err => {
        console.error('[useExploration] autosave failed', err)
      })
    },
    300
  )

  // id 改變時（切換到不同探索，或同一路由帶不同 ?q）：先把舊紀錄的待寫入內容存檔，再載入新紀錄
  watch(id, (newId, oldId) => {
    if (oldId !== undefined) flush()
    void load(newId)
  })

  onUnmounted(flush)

  const setAnswer = (questionIndex: number, text: string) => {
    const prev = exploration.value
    if (!prev) return
    const now = new Date().toISOString()
    const answers: Answer[] = [...prev.answers]
    const idx = answers.findIndex(a => a.questionIndex === questionIndex)
    if (idx >= 0) answers[idx] = { ...answers[idx], text, updatedAt: now }
    else answers.push({ questionIndex, text, updatedAt: now })
    exploration.value = { ...prev, answers, updatedAt: now }
  }

  const finish = (summary: SummarySection[], card: SelfAwarenessCard) => {
    const prev = exploration.value
    if (!prev) return
    exploration.value = { ...prev, summary, card, status: 'completed', updatedAt: new Date().toISOString() }
  }

  const value: ExplorationContextValue = { exploration, loading, setAnswer, finish }
  provide(ExplorationKey, value)
  return value
}

export function useExploration(): ExplorationContextValue {
  const ctx = inject(ExplorationKey)
  if (!ctx) throw new Error('useExploration must be used within a component tree that called provideExploration()')
  return ctx
}

